from django.contrib import admin


from api.users.models import KYCVerification, User

from api.users.models import KYCVerification, User, UserActivityLog


@admin.register(User)
class UserAdmin(admin.ModelAdmin):
    """Read-mostly user admin.

    Registered so a Django superuser can actually find an account - without
    this there was no user page at all, despite the bootstrapped Super Admin
    being given is_staff/is_superuser specifically to reach /admin/.

    `role` and `status` are read-only on purpose: both have service-layer
    rules behind them (staff_service for role changes, user_admin_service for
    suspension, each of which revokes sessions and writes an activity log
    entry). Editing them straight into the database here would skip all of
    that and leave no trace of who decided what, so those changes belong to
    the API.
    """

    list_display = (
        "id",
        "email",
        "first_name",
        "last_name",
        "role",
        "status",
        "is_active",
        "last_login",
        "created_datetime",
    )
    list_filter = ("role", "status", "is_active")
    search_fields = ("email", "first_name", "last_name")
    ordering = ("-created_datetime",)
    readonly_fields = (
        "id",
        "role",
        "status",
        "password",
        "last_login",
        "failed_login_attempts",
        "locked_until",
        "created_datetime",
        "updated_datetime",
    )



@admin.register(KYCVerification)
class KYCVerificationAdmin(admin.ModelAdmin):
    """KYC submissions, read-only.

    Approval and rejection go through kyc_service (which notifies the
    submitter and logs the reviewer), so status is never edited here.
    """

    list_display = ("id", "user", "document_type", "status", "created_datetime")
    list_filter = ("status", "document_type")
    search_fields = ("user__email", "id_number")



