@admin.register(UserActivityLog)
class UserActivityLogAdmin(admin.ModelAdmin):
    """The platform's audit trail, fully read-only.

    An audit log that can be edited from the admin is not an audit log, so
    every field is read-only and rows cannot be added or deleted here.
    """

    list_display = (
        "id",
        "user",
        "category",
        "action",
        "summary",
        "activity_datetime",
    )
    list_filter = ("category", "action")
    search_fields = ("user__email", "summary")
    ordering = ("-activity_datetime",)

    def get_readonly_fields(self, request, obj=None):
        return [field.name for field in self.model._meta.fields]

    def has_add_permission(self, request):
        return False

    def has_change_permission(self, request, obj=None):
        return False

    def has_delete_permission(self, request, obj=None):
        return False

